mapper.select:


    r.del_flag = '0'

        and r.report_code = #{reportCode}


        and r.stat_month = #{statMonth}


        and r.region_code = #{regionCode}

    ${params.regionDataScope}
    ${params.enterpriseDataScope}

        and r.report_status = #{reportStatus}


        and r.metric_count  >=  #{minMetricCount}


        and r.metric_count  <=  #{maxMetricCount}


        and r.metric_rate  >=  #{minMetricRate}


        and r.metric_rate  <=  #{maxMetricRate}


        and exists (
            select 1
            from t_stat_report_item i
            where i.report_id = r.report_id
              and (
                i.item_name like concat('%', #{keyword}, '%')
                or i.item_dimension like concat('%', #{keyword}, '%')
              )
        )


        and exists (
            select 1
            from t_stat_report_item i
            where i.report_id = r.report_id
              and i.item_dimension like concat('%', #{itemDimension}, '%')
        )


        and exists (
            select 1
            from t_stat_report_item i
            where i.report_id = r.report_id
              and (i.item_dimension = #{sourceModule} or i.item_name like concat('%', #{sourceModule}, '%'))
        )


        and exists (
            select 1
            from t_stat_report_item i
            where i.report_id = r.report_id
              and (i.item_dimension = #{riskCategory} or i.item_name like concat('%', #{riskCategory}, '%'))
        )


        and exists (
            select 1
            from t_stat_report_item i
            where i.report_id = r.report_id
              and i.item_dimension like concat('%', #{batchNo}, '%')
        )


order by r.generated_time desc, r.report_id desc


where r.report_code = #{reportCode}
  and r.stat_month = #{statMonth}
  and r.region_code = #{regionCode}
  and r.del_flag = '0'
limit 1

mapper.insert:
insert into t_stat_report (
    report_code, report_name, stat_month, region_code, report_status, metric_count, metric_amount,
    metric_rate, report_summary, attachment_url, source_mode, generated_time, del_flag,
    create_by, create_time, update_by, update_time, remark
) values (
    #{reportCode}, #{reportName}, #{statMonth}, #{regionCode}, #{reportStatus}, #{metricCount},
    #{metricAmount}, #{metricRate}, #{reportSummary}, #{attachmentUrl}, #{sourceMode},
    #{generatedTime}, '0', #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{remark}
)

insert into t_stat_report_item (
    report_id, item_category, item_name, item_dimension, metric_count, metric_value, metric_rate, sort_no
) values (
    #{reportId}, #{itemCategory}, #{itemName}, #{itemDimension}, #{metricCount},
    #{metricValue}, #{metricRate}, #{sortNo}
)

mapper.select:
select null as item_id, null as report_id, 'WARNING_OVERVIEW' as item_category, w.source_module as item_name, w.source_module as item_dimension, count(1) as metric_count, cast(sum(case when w.warn_status = '2' then 1 else 0 end) as decimal(16,2)) as metric_value, case when count(1) = 0 then 0 else round(sum(case when w.warn_status = '2' then 1 else 0 end) / count(1) * 100, 2) end as metric_rate, 0 as sort_no from t_warning w where date_format(w.create_time, '%Y-%m') = #{statMonth}
and w.region_code like concat(#{regionPrefix}, '%')
group by w.source_module order by metric_count desc, w.source_module

select null as item_id, null as report_id, 'UNION_SUPERVISION' as item_category, source_name as item_name, source_name as item_dimension, count(1) as metric_count, cast(sum(case when status in ('closed', 'done', 'processed', '1') then 1 else 0 end) as decimal(16,2)) as metric_value, case when count(1) = 0 then 0 else round(sum(case when status in ('closed', 'done', 'processed', '1') then 1 else 0 end) / count(1) * 100, 2) end as metric_rate, 0 as sort_no from ( select 'COMPLAINT' as source_name, status, create_time, del_flag, region_code from ygb_worker_complaint union all select 'LEGAL' as source_name, status, create_time, del_flag, region_code from ygb_worker_legal_consult union all select 'FEEDBACK' as source_name, status, create_time, del_flag, null as region_code from ygb_worker_feedback ) u where u.del_flag = '0' and date_format(u.create_time, '%Y-%m') = #{statMonth}
and (u.region_code is null or u.region_code like concat(#{regionPrefix}, '%'))
group by source_name order by metric_count desc, source_name

select null as item_id, null as report_id, 'CUSTOM' as item_category, item_name, item_dimension, metric_count, metric_value, metric_rate, 0 as sort_no from ( select '风险企业' as item_name, 'RISK_ENTERPRISE' as item_dimension, count(1) as metric_count, cast(sum(ifnull(credit_score, 0)) as decimal(16,2)) as metric_value, round(avg(ifnull(credit_score, 0)), 2) as metric_rate from t_credit_score where stat_month = #{statMonth} and del_flag = '0'
and region_code like concat(#{regionPrefix}, '%')
union all select '预警闭环' as item_name, 'WARNING_CLOSED' as item_dimension, count(1) as metric_count, cast(sum(case when warn_status = '2' then 1 else 0 end) as decimal(16,2)) as metric_value, case when count(1) = 0 then 0 else round(sum(case when warn_status = '2' then 1 else 0 end) / count(1) * 100, 2) end as metric_rate from t_warning where date_format(create_time, '%Y-%m') = #{statMonth}
and region_code like concat(#{regionPrefix}, '%')
) c order by metric_count desc, item_name

select count(1)
from t_employment_proportion
where stat_month = #{statMonth}
  and warning_level = #{warningLevel}

    and region_code like concat(#{regionPrefix}, '%')

select null as item_id, null as report_id, 'SPECIAL_RECTIFICATION' as item_category, coalesce(nullif(enterprise_name, ''), nullif(person_name, ''), region_code) as item_name, coalesce(nullif(business_type, ''), nullif(risk_level, ''), 'SPECIAL_RECTIFICATION') as item_dimension, count(1) as metric_count, cast(sum(case when workflow_status in ('closed','done','processed','3','2') or status in ('1','closed','done','processed') then 1 else 0 end) as decimal(16,2)) as metric_value, case when count(1) = 0 then 0 else round(sum(case when workflow_status in ('closed','done','processed','3','2') or status in ('1','closed','done','processed') then 1 else 0 end) / count(1) * 100, 2) end as metric_rate, 0 as sort_no from ygb_br_special_rectification where del_flag = '0' and stat_month = #{statMonth}
and region_code like concat(#{regionPrefix}, '%')
group by coalesce(nullif(business_type, ''), nullif(risk_level, ''), 'SPECIAL_RECTIFICATION'), coalesce(nullif(enterprise_name, ''), nullif(person_name, ''), region_code) order by metric_count desc, item_name
